"""Overdue fee statements: python3 fees.py INPUT_DIR OUTPUT_FILE"""
import configparser
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def cents(text):
    return int((Decimal(text.strip()) * 100).to_integral_value())


def patron_key(text):
    digits = re.sub(r"\D", "", text or "")
    return int(digits) if digits else None


def parse_date(text):
    return date.fromisoformat(text.strip())


def parse_offset(text):
    m = re.fullmatch(r"([+-])(\d{1,2}):?(\d{2})?", text.strip())
    sign = -1 if m.group(1) == "-" else 1
    return sign * timedelta(hours=int(m.group(2)), minutes=int(m.group(3) or 0))


def parse_utc(text):
    text = text.strip()
    if text.endswith("Z") or text.endswith("z"):
        text = text[:-1] + "+00:00"
    dt = datetime.fromisoformat(text)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc).replace(tzinfo=None)


def parse_local(text):
    m = re.fullmatch(r"\s*(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2})(?::(\d{1,2}))?(?::(\d{1,2}))?\s*", text)
    y, mo, d, h, mi, s = m.groups()
    return datetime(int(y), int(mo), int(d), int(h), int(mi or 0), int(s or 0))


def read_policy(path):
    cp = configparser.ConfigParser(interpolation=None, comment_prefixes=("#",), inline_comment_prefixes=None,
                                   delimiters=("=",))
    cp.optionxform = lambda s: s.strip().lower()
    with open(path, encoding="utf-8-sig") as f:
        cp.read_file(f)
    pol = {"library": cp.get("statement", "library").strip(),
           "start": parse_date(cp.get("statement", "period_start")),
           "end": parse_date(cp.get("statement", "period_end"))}
    offset = parse_offset(cp.get("clock", "offset")) if cp.has_option("clock", "offset") else timedelta(0)
    changes = []
    raw = cp.get("clock", "changes", fallback="") if cp.has_section("clock") else ""
    for part in raw.split(";"):
        part = part.strip()
        if not part:
            continue
        inst, off = part.split()
        changes.append((parse_utc(inst), parse_offset(off)))
    changes.sort(key=lambda c: c[0])
    pol["offset"] = offset
    pol["changes"] = changes
    pol["items"] = {}
    pol["cats"] = {}
    for sec in cp.sections():
        kind, _, name = sec.partition(":")
        kind = kind.strip().lower()
        name = name.strip()
        if kind == "item":
            pol["items"][name.lower()] = {
                "name": name,
                "loan_days": int(cp.get(sec, "loan_days")),
                "renewals": int(cp.get(sec, "renewals")),
                "grace": int(cp.get(sec, "grace_days")),
                "daily": cents(cp.get(sec, "daily")),
                "loan_cap": cents(cp.get(sec, "loan_cap")),
            }
        elif kind == "category":
            cap = cp.get(sec, "statement_cap").strip()
            ex = cp.get(sec, "exempt", fallback="")
            pol["cats"][name.lower()] = {
                "name": name,
                "cap": None if cap.lower() == "none" else cents(cap),
                "discount": int(cp.get(sec, "discount").strip() or 0),
                "exempt": {x.strip().lower() for x in ex.split(",") if x.strip()},
            }
    return pol


def read_csv(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        rows = list(csv.DictReader(f))
    out = []
    for r in rows:
        out.append({(k or "").strip(): (v or "").strip() for k, v in r.items() if k is not None})
    return out


def local_from_utc(utc, pol):
    off = pol["offset"]
    for inst, o in pol["changes"]:
        if inst <= utc:
            off = o
        else:
            break
    return utc + off


def read_events(indir, pol):
    exdir = os.path.join(indir, "exports")
    events = {}
    for name in sorted(os.listdir(exdir)):
        path = os.path.join(exdir, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            for r in read_csv(path):
                if not r.get("event"):
                    continue
                if r["event"] in events:
                    continue
                r = dict(r)
                r["_local"] = parse_local(r["time"])
                events[r["event"]] = r
        elif name.endswith(".jsonl"):
            with open(path, encoding="utf-8-sig") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    r = json.loads(line)
                    r = {k: ("" if v is None else str(v).strip()) for k, v in r.items()}
                    if not r.get("event") or r["event"] in events:
                        continue
                    r["_local"] = local_from_utc(parse_utc(r["at"]), pol)
                    events[r["event"]] = r
    for e in events.values():
        e["type"] = e.get("type", "").lower()
        e["via"] = e.get("via", "").lower()
    return events


class Calendar:
    def __init__(self, branches, rows):
        self.open_days = branches
        self.rows = {}
        for r in rows:
            b = r["branch"].strip()
            b = "*" if b == "*" else b.upper()
            d = r["date"].strip()
            if ".." in d:
                a, z = d.split("..")
            else:
                a = z = d
            self.rows.setdefault(b, []).append((parse_date(a), parse_date(z), r["status"].strip().lower()))
        self.cache = {}

    def is_open(self, branch, day):
        key = (branch, day)
        if key in self.cache:
            return self.cache[key]
        res = None
        for b in (branch, "*"):
            for a, z, st in self.rows.get(b, []):
                if a <= day <= z:
                    res = (st == "open")
                    break
            if res is not None:
                break
        if res is None:
            res = WEEKDAYS[day.weekday()] in self.open_days.get(branch, set())
        self.cache[key] = res
        return res

    def next_open(self, branch, day):
        for _ in range(3660):
            if self.is_open(branch, day):
                return day
            day += timedelta(days=1)
        return day


def main(indir, outfile):
    pol = read_policy(os.path.join(indir, "policy.ini"))
    start, end = pol["start"], pol["end"]

    branch_rows = read_csv(os.path.join(indir, "branches.csv"))
    branch_ids = [r["branch"] for r in branch_rows]
    branch_map = {b.upper(): b for b in branch_ids}
    open_days = {r["branch"].upper(): {w[:3].lower() for w in r["open_days"].split()} for r in branch_rows}
    cal = Calendar(open_days, read_csv(os.path.join(indir, "calendar.csv")))

    patrons = {}
    for r in read_csv(os.path.join(indir, "patrons.csv")):
        patrons.setdefault(patron_key(r["patron"]), []).append((parse_date(r["since"]), r["category"], r["patron"]))
    for v in patrons.values():
        v.sort(key=lambda x: x[0])

    def category_on(pk, day):
        cur = None
        for since, cat, _ in patrons[pk]:
            if since <= day:
                cur = cat
        if cur is None:
            cur = patrons[pk][0][1]
        return pol["cats"][cur.strip().lower()]

    waivers = {}
    for r in read_csv(os.path.join(indir, "waivers.csv")):
        if r["status"].strip().lower() != "active":
            continue
        val = r["value"].strip()
        waivers.setdefault(patron_key(r["patron"]), []).append(
            (r["loan"].strip(), None if val.lower() == "full" else cents(val)))

    events = read_events(indir, pol)
    cancelled = set()
    for e in events.values():
        if e["type"] == "void" and e.get("target"):
            cancelled.add(e["target"])
    live = [e for e in events.values() if e["type"] != "void" and e["event"] not in cancelled]

    checkouts = {}
    others = {}
    for e in live:
        if e["type"] == "checkout":
            checkouts[e["loan"]] = e
        elif e["type"] in ("renew", "return"):
            others.setdefault(e["loan"], []).append(e)

    stmts = {}
    for loan_id, co in checkouts.items():
        cdate = co["_local"].date()
        if cdate > end:
            continue
        item = pol["items"][co["item_type"].lower()]
        branch = branch_map.get(co["branch"].upper(), co["branch"])
        bkey = branch.upper()
        due = cal.next_open(bkey, cdate + timedelta(days=item["loan_days"]))
        renewals = 0
        returned = None
        for e in sorted(others.get(loan_id, []), key=lambda x: x["_local"]):
            d = e["_local"].date()
            if e["type"] == "renew":
                if d <= due and renewals < item["renewals"] and d <= end:
                    renewals += 1
                    due = cal.next_open(bkey, d + timedelta(days=item["loan_days"]))
            else:
                returned = d - timedelta(days=1) if e["via"] == "dropbox" else d
                break
        if returned is not None and returned > end:
            returned = None
        if returned is not None and returned < start:
            continue
        endday = returned if returned is not None else end
        overdue = 0
        d = due + timedelta(days=1)
        while d <= endday:
            if cal.is_open(bkey, d):
                overdue += 1
            d += timedelta(days=1)
        if overdue < 1:
            continue
        charged = overdue if overdue > item["grace"] else 0
        fee = charged * item["daily"]
        pk = patron_key(co["patron"])
        cat = category_on(pk, cdate)
        if item["name"].lower() in cat["exempt"]:
            fee = 0
        fee = min(fee, item["loan_cap"])
        fee = (fee * (100 - cat["discount"]) + 50) // 100
        waived = 0
        full = False
        total = 0
        for wl, wv in waivers.get(pk, []):
            if wl == "*" or wl == loan_id:
                if wv is None:
                    full = True
                else:
                    total += wv
        waived = fee if full else min(total, fee)
        stmts.setdefault(pk, []).append({
            "loan": loan_id, "item": co.get("item", ""), "item_type": item["name"], "branch": branch,
            "checkout": cdate.isoformat(), "due": due.isoformat(),
            "returned": returned.isoformat() if returned is not None else None,
            "overdue_days": overdue, "charged_days": charged,
            "assessed": fee, "waived": waived, "capped": 0, "billed": fee - waived,
            "_due": due,
        })

    statements = []
    for pk in sorted(stmts):
        loans = sorted(stmts[pk], key=lambda x: (x["_due"], x["loan"]))
        cat = category_on(pk, end)
        if cat["cap"] is not None:
            excess = sum(l["billed"] for l in loans) - cat["cap"]
            for l in sorted(loans, key=lambda x: (x["_due"], x["loan"]), reverse=True):
                if excess <= 0:
                    break
                give = min(excess, l["billed"])
                l["capped"] = give
                l["billed"] -= give
                excess -= give
        for l in loans:
            del l["_due"]
        name = patrons[pk][-1][2]
        for since, _, nm in patrons[pk]:
            if since <= end:
                name = nm
        st = {"patron": name, "category": cat["name"], "loans": loans}
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(l[k] for l in loans)
        statements.append(st)

    summary = []
    for b in branch_ids:
        row = {"branch": b, "loans": 0, "charged_days": 0, "assessed": 0, "waived": 0, "capped": 0, "billed": 0}
        for st in statements:
            for l in st["loans"]:
                if l["branch"] == b:
                    row["loans"] += 1
                    for k in ("charged_days", "assessed", "waived", "capped", "billed"):
                        row[k] += l[k]
        summary.append(row)

    result = {"library": pol["library"], "period": {"start": start.isoformat(), "end": end.isoformat()},
              "statements": statements, "branches": summary}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
